let windowSize = 2h;

// S99: Passive Recon — 제안 스키마(미배포, 수동수집은 원천적으로 로깅 불가). UAVOpAudit_CL을 전역 게이트로 대리 사용 (UAVId 없음)
let S99Time = toscalar(
    UAVOpAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType in ('recon_scan','passive_scan')
    | summarize min(TimeGenerated));

// S15: BMS Spoofing — UAVTelemetry_CL 배터리 필드의 비현실적 판독값을 스푸핑 지표로 사용
let S15 =
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where BatteryVoltage_mV <= 0 or BatteryRemaining_pct > 100 or BatteryRemaining_pct < 0
    | extend Stage = 'S15', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S6: Config Tamper — UAVConfigAudit_CL, 5분 버킷당 대량 ParamId 변경
let S6 =
    UAVConfigAudit_CL
    | where TimeGenerated > ago(windowSize)
    | summarize ParamChangeCount = count() by UAVId, bin(TimeGenerated, 5m)
    | where ParamChangeCount >= 5
    | extend Stage = 'S6'
    | project TimeGenerated, Stage, UAVId;

// S5: AOI Excursion/Mission Fail — UAVFailsafe_CL 고심각도 이벤트를 대리 지표로 사용
let S5 =
    UAVFailsafe_CL
    | where TimeGenerated > ago(windowSize)
    | where Severity >= 3
    | extend Stage = 'S5', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

union S15, S6, S5
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by UAVId
| extend HasS99 = isnotnull(S99Time)
| extend EffectiveStageCount = StageCount + toint(HasS99)
| where EffectiveStageCount >= 3
| extend CampaignType = "C22_수동정찰_BMS스푸핑_파라미터리셋_Failsafe억제"
| extend StepSummary = strcat("S99(전역)@", tostring(S99Time), " | Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, UAVId, StagesSeen, EffectiveStageCount, CampaignType, StepSummary, Severity
